// Concatenates supabase/migrations/*.sql into supabase/setup.sql, a single
// transactional script to paste into the Supabase SQL Editor.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const migrationsDir = join(root, "supabase", "migrations");
const files = readdirSync(migrationsDir).filter((file) => file.endsWith(".sql")).sort();

const header = `-- Dressing: full database setup for the Supabase SQL Editor.
-- GENERATED by \`pnpm db:bundle\` from supabase/migrations — do not edit by hand.
--
-- Run it once on an empty project (SQL Editor > New query > paste > Run).
-- Everything runs in one transaction: on error, nothing is applied.
-- Do not combine with \`supabase db push\` / the GitHub integration, which apply
-- the same migrations (see README).
`;

const body = files
  .map((file) => `-- ===========================================================================\n-- ${file}\n-- ===========================================================================\n\n${readFileSync(join(migrationsDir, file), "utf-8").trim()}\n`)
  .join("\n");

writeFileSync(join(root, "supabase", "setup.sql"), `${header}\nbegin;\n\n${body}\ncommit;\n`);
console.log(`supabase/setup.sql written from ${files.length} migrations.`);
